  "u_b031faf6c80e6ce2": ".hub-card{transition:transform .18s ease, border-color .18s ease, box-shadow .18s ease;} .hub-card:hover{transform:translateY(-3px); box-shadow:0 24px 60px rgba(0,0,0,.55);} .hub-chip{transition:background .15s ease, color .15s ease, border-color .15s ease; cursor:pointer;} .hub-chip:hover{border-color:rgba(255,195,0,.6);} .hub-btn{transition:filter .15s ease, transform .12s ease; cursor:pointer;} .hub-btn:hover{transform:translateY(-1px); filter:brightness(1.25);} .hub-panel::-webkit-scrollbar{width:8px;} .hub-panel::-webkit-scrollbar-thumb{background:rgba(255,255,255,.14);border-radius:8px;} .hub-panel::-webkit-scrollbar-track{background:transparent;} @keyframes hubPulse{0%,100%{opacity:.45}50%{opacity:1}} .hub-loading{animation:hubPulse 1.4s ease infinite;} .vault-standalone > .hub-panel{height:auto!important;min-height:calc(100vh - 120px)!important;overflow:visible!important;padding-right:0!important;max-width:980px;margin:0 auto;gap:22px!important;} .vault-standalone > .hub-panel > section{padding:22px 0 8px;min-height:auto;} .vault-standalone > .hub-panel > section:nth-of-type(1){min-height:72vh;display:flex;flex-direction:column;} .vault-standalone > .hub-panel > section:nth-of-type(2){min-height:46vh;} .vault-standalone > .hub-panel > section:nth-of-type(3){display:none!important;} .vault-standalone .hub-card{border-radius:22px;} @media (max-width: 720px){.vault-standalone{padding-left:12px!important;padding-right:12px!important}.vault-standalone > .hub-panel{max-width:100%;gap:18px!important}.vault-standalone > .hub-panel > section:nth-of-type(1){min-height:68vh}}",
